#include <iostream>

long long gcd_step(long long a, long long b) {
    if (b == 0) return a;
    return gcd_step(b, a % b);
}

long long gcd_rec(long long a, long long b) {
    return gcd_step(a, b);
}

int main() {
    long long a, b;
    std::cin >> a >> b;
    std::cout << gcd_rec(a, b) << std::endl;
    return 0;
}

