#include <iostream>
#include <string>
#include <vector>

void plan(int disks, char from, char to, char aux, std::vector<std::string> &out) {
    if (disks == 0) return;
    plan(disks - 1, from, aux, to, out);
    out.push_back("disk " + std::to_string(disks) + ": " + from + "->" + to);
    plan(disks - 1, aux, to, from, out);
}

std::vector<std::string> hanoi_plan(int n) {
    std::vector<std::string> out;
    plan(n, 'A', 'C', 'B', out);
    return out;
}

void emit(const std::vector<std::string> &moves, std::size_t i) {
    if (i == moves.size()) {
        std::cout << std::endl;
        return;
    }
    std::cout << moves[i];
    if (i + 1 < moves.size()) std::cout << ' ';
    emit(moves, i + 1);
}

int main() {
    int n;
    std::cin >> n;
    emit(hanoi_plan(n), 0);
    return 0;
}

