long long total_from(const std::vector<int> &v, int i) {
    if (i == (int)v.size()) return 0;
    return v[i] + total_from(v, i + 1);
}

long long vector_sum(const std::vector<int> &v) {
    return total_from(v, 0);
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> v(n);
    for (int &x : v) std::cin >> x;
    std::cout << vector_sum(v) << std::endl;
    return 0;
}

