int check_span(const std::string &s, int lo, int hi) {
    if (lo >= hi) return 1;
    if (s[lo] != s[hi]) return 0;
    return check_span(s, lo + 1, hi - 1);
}

int is_palindrome(const std::string &s) {
    return check_span(s, 0, (int)s.size() - 1);
}

int main() {
    std::string word;
    std::cin >> word;
    std::cout << is_palindrome(word) << std::endl;
    return 0;
}

