long long pick(const std::vector<int> &v, int i, int left) {
    if (i == (int)v.size()) return left == 0 ? 1 : 0;
    return pick(v, i + 1, left - v[i]) + pick(v, i + 1, left);
}

long long count_subsets(const std::vector<int> &v, int S) {
    return pick(v, 0, S);
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> v(n);
    for (int &x : v) std::cin >> x;
    int S;
    std::cin >> S;
    std::cout << count_subsets(v, S) << std::endl;
    return 0;
}

