long long count_from(int freq[], int remaining) {
    if (remaining == 0) return 1;
    long long total = 0;
    for (int c = 0; c < 26; c++) {
        if (freq[c] > 0) {
            freq[c]--;
            total += count_from(freq, remaining - 1);
            freq[c]++;
        }
    }
    return total;
}

long long count_arrangements(const std::string &s) {
    int freq[26];
    for (int i = 0; i < 26; i++) freq[i] = 0;
    for (int i = 0; i < (int)s.size(); i++) freq[s[i] - 'a']++;
    return count_from(freq, (int)s.size());
}

int main() {
    int n;
    std::cin >> n;
    std::string word;
    std::cin >> word;
    std::cout << count_arrangements(word) << std::endl;
    return 0;
}

