long long count_rolls(int target) {
    if (target == 0) return 1;
    if (target < 0) return 0;
    long long total = 0;
    for (int face = 1; face <= 6; face++) total += count_rolls(target - face);
    return total;
}

int main() {
    int target;
    std::cin >> target;
    std::cout << count_rolls(target) << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

long long walk(const std::vector<std::vector<int>> &grid, int r, int c) {
    if (r >= (int)grid.size() || c >= (int)grid[0].size() || grid[r][c] == 1) return 0;
    if (r == (int)grid.size() - 1 && c == (int)grid[0].size() - 1) return 1;
    return walk(grid, r + 1, c) + walk(grid, r, c + 1);
}

long long count_paths(const std::vector<std::vector<int>> &grid) {
    return walk(grid, 0, 0);
}

int main() {
    int r, c;
    std::cin >> r >> c;
    std::vector<std::vector<int>> grid(r, std::vector<int>(c));
    for (int i = 0; i < r; i++)
        for (int j = 0; j < c; j++) std::cin >> grid[i][j];
    std::cout << count_paths(grid) << std::endl;
    return 0;
}

#include <iostream>
