std::string kth_permutation(int n, const std::string &letters, long long k) {
    std::string pool = letters;
    std::string out = "";
    long long left = k - 1;
    long long block = 1;
    for (int i = 2; i < n; i++) block *= i;
    for (int pos = 0; pos < n; pos++) {
        int idx = (int)(left / block);
        left -= (long long)idx * block;
        out += pool[idx];
        pool.erase(pool.begin() + idx);
        if (pos + 1 < n) block /= (n - 1 - pos);
    }
    return out;
}

int main() {
    int n;
    std::cin >> n;
    std::string letters;
    std::cin >> letters;
    long long k;
    std::cin >> k;
    std::cout << kth_permutation(n, letters, k) << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

void extend(const std::vector<int> &v, int start, int left,
            std::vector<int> &cur, std::vector<std::vector<int>> &out) {
    if (left == 0) {
        out.push_back(cur);
        return;
    }
    for (int j = start; j < (int)v.size(); j++) {
        if (v[j] > left) break;
        cur.push_back(v[j]);
        extend(v, j + 1, left - v[j], cur, out);
        cur.pop_back();
    }
}

std::vector<std::vector<int>> subset_sums(const std::vector<int> &v, int S) {
    std::vector<std::vector<int>> out;
    std::vector<int> cur;
    for (int start = 0; start < (int)v.size(); start++) {
        if (v[start] > S) break;
        cur.push_back(v[start]);
        extend(v, start + 1, S - v[start], cur, out);
        cur.pop_back();
    }
    return out;
}

void emit(const std::vector<std::vector<int>> &rows, std::size_t i) {
    if (i == rows.size()) return;
    for (std::size_t j = 0; j < rows[i].size(); j++) {
        if (j > 0) std::cout << ' ';
        std::cout << rows[i][j];
    }
    std::cout << std::endl;
    emit(rows, i + 1);
}

int main() {
