    std::cin >> n;
    std::vector<int> v(n);
    for (int &x : v) std::cin >> x;
    int S;
    std::cin >> S;
    emit(subset_sums(v, S), 0);
    return 0;
}

#include <iostream>

long long place_queens(int col[], int n, int row) {
    if (row == n) return 1;
    long long total = 0;
    for (int c = 0; c < n; c++) {
        int safe = 1;
        for (int pr = 0; pr < row; pr++) {
            if (col[pr] == c || row - pr == c - col[pr] || row - pr == col[pr] - c) safe = 0;
        }
        if (safe) {
            col[row] = c;
            total += place_queens(col, n, row + 1);
        }
    }
    return total;
}

long long nqueens_count(int n) {
    int col[8];
    return place_queens(col, n, 0);
}

int main() {
    int n;
    std::cin >> n;
    std::cout << nqueens_count(n) << std::endl;
    return 0;
}
